cd "[private value removed]" && python - <<'EOF'
import json
d = json.load(open('.local/stage1-topo.json'))
def walk(o, depth=0, key=''):
    if depth>3: return
    if isinstance(o, dict):
        for k,v in list(o.items())[:20]:
            print('  '*depth + str(k), type(v).__name__, (len(v) if isinstance(v,(list,dict)) else v if not isinstance(v,str) or len(v)<80 else v[:80]))
            walk(v, depth+1)
    elif isinstance(o, list):
        print('  '*depth + f'[{len(o)} items]')
        if o: walk(o[0], depth+1)
walk(d)
EOF
